        p: p,
        id: p.getAttribute("data-edge"),
        from: p.getAttribute("data-from"),
        to: p.getAttribute("data-to"),
        cond: p.getAttribute("data-cond") || "",
        mod: p.getAttribute("data-mod") || "",
