# hive path can be the same string in two different roles -- `/a/b` is a cell in
# one colony and a hive in another -- and one id space that could not tell them
# apart would silently patch the wrong object.
ROOT_ID = "canvy"
NODE_PREFIX = "n/"
HIVE_PREFIX = "h/"
EDGE_PREFIX = "e/"

# ---------------------------------------------------------------------------
# The component library. Data, not code: a `web` cell's `component.define` takes
# a template written in the closed four-form language ({{prop}}, {{&prop}},
# {{children}}, {{#if prop}}...{{/if}}) and nothing else, and it parses it at
# DEFINITION time -- so a mistake here is answered to this cell, not rendered as
# a blank area on somebody's screen.
#
# `{{&client_css}}` and `{{&client_js}}` are raw on purpose, and the schema types
# them `"html"`, which is what makes them raw: a `{{&prop}}` whose schema does not
# say `"html"` is escaped instead, and a stylesheet rendered escaped is a page
# with no style at all. Everything else is escaped by default -- a cell path is
# database content and a name carrying `<script>` must not be able to close a tag.

SHELL_TEMPLATE = (
    '<div class="canvy" id="canvy" phx-hook="Canvy" data-title="{{title}}"'
    ' data-nw="{{nw}}" data-nh="{{nh}}" data-pad-side="{{pad_side}}"'
    ' data-pad-top="{{pad_top}}" data-pad-bot="{{pad_bot}}" data-nest="{{nest}}">'
    "<style>{{&client_css}}</style>"
    "<script>{{&client_js}}</script>"
    '<svg class="stage" xmlns="http://www.w3.org/2000/svg" viewBox="{{viewbox}}"'
    ' preserveAspectRatio="xMidYMid meet">'
